class Solution { public int shortestPathAllKeys(String[] grid){int rows=grid.length,columns=grid[0].length(),startRow=0,startColumn=0,target=0;for(int r=0;r<rows;r++)for(int c=0;c<columns;c++){char value=grid[r].charAt(c);if(value=='@'){startRow=r;startColumn=c;}else if(value>='a'&&value<='f')target|=1<<(value-'a');}boolean[][][] seen=new boolean[rows][columns][64];Queue<int[]> queue=new ArrayDeque<>();queue.offer(new int[]{startRow,startColumn,0,0});seen[startRow][startColumn][0]=true;int[] directions={-1,0,1,0,-1};while(!queue.isEmpty()){int[] state=queue.poll();if(state[2]==target)return state[3];for(int d=0;d<4;d++){int r=state[0]+directions[d],c=state[1]+directions[d+1];if(r<0||r>=rows||c<0||c>=columns||grid[r].charAt(c)=='#')continue;char value=grid[r].charAt(c);int mask=state[2];if(value>='A'&&value<='F'&&(mask&(1<<(value-'A')))==0)continue;if(value>='a'&&value<='f')mask|=1<<(value-'a');if(!seen[r][c][mask]){seen[r][c][mask]=true;queue.offer(new int[]{r,c,mask,state[3]+1});}}}return -1;} }
